const input = $input.item.json;
const title = input.title || "Ventureify";
const sector = input.sector || "Logistics";

// Inline execution or import of competitor-tool.js
let competitorInsights = "";
try {
  const path = require('path');
  const competitorTool = require(path.resolve(__dirname, '../scripts/competitor-tool.js'));
  competitorInsights = competitorTool.build(sector).text;
} catch (e) {
  if (sector.toLowerCase().includes("logistics")) {
    competitorInsights = "Incumbents: Rabbit Mart, Upuse, Bosta. Strengths: Fleet density. Weaknesses: Heavy fossil fuel reliance.";
  } else {
    competitorInsights = "Incumbents: Global SaaS providers. Strengths: Feature maturity. Weaknesses: Lack of local language support.";
  }
}

return {
  json: {
    prompt: `Analyze feasibility and risks for: ${title}. Competitor context: ${competitorInsights}`,
    model: "gemini-1.5-flash"
  }
};
